using Cosmos.Application.Abstractions.Persistence;
using Cosmos.Application.Abstractions.Services;
using Cosmos.Contracts.Audit;
using Cosmos.Contracts.Common;
using Cosmos.Contracts.HsnGst;
using Cosmos.Shared.Exceptions;
using Cosmos.Shared.Responses;
using Cosmos.Shared.Security;
using FluentValidation;

namespace Cosmos.Application.Services;
public sealed class HsnGstService(IHsnGstRepository repository, IAuditRepository audit, ICurrentUser user, IValidator<SaveHsnSacRequest> hsnValidator, IValidator<SaveGstRateRuleVersionRequest> rateValidator, IValidator<RetireHsnMappingRequest> retireValidator) : IHsnGstService
{
    public async Task<ApiResponse<PagedResult<HsnSacDto>>> GetHsnSacsAsync(HsnSacListQuery q, CancellationToken ct) => ApiResponse<PagedResult<HsnSacDto>>.Success(await repository.GetHsnSacsAsync(q, ct));
    public async Task<ApiResponse<HsnSacDto>> GetHsnSacAsync(long id, CancellationToken ct) => ApiResponse<HsnSacDto>.Success(await repository.GetHsnSacAsync(id, ct) ?? throw new NotFoundException("HSN/SAC record was not found."));
    public async Task<ApiResponse<HsnSacDto>> SaveHsnSacAsync(long? id, SaveHsnSacRequest request, CancellationToken ct) { await ValidationRunner.ValidateAsync(hsnValidator, request, ct); var before=id is null?null:await repository.GetHsnSacAsync(id.Value,ct); var saved=await repository.SaveHsnSacAsync(id, request, user.UserId, ct); await audit.AddAsync(new AuditEntryRequest("HsnSacMasters",saved.Id.ToString(),id is null?"Create":"Update",before is null?null:AuditSerializer.Serialize(before),AuditSerializer.Serialize(saved),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse<HsnSacDto>.Success(saved,id is null?"HSN/SAC created.":"HSN/SAC updated."); }
    public async Task<ApiResponse<PagedResult<GstRateRuleVersionDto>>> GetRateVersionsAsync(GstRateRuleVersionListQuery q, CancellationToken ct) => ApiResponse<PagedResult<GstRateRuleVersionDto>>.Success(await repository.GetRateVersionsAsync(q, ct));
    public async Task<ApiResponse<GstRateRuleVersionDto>> SaveRateVersionAsync(SaveGstRateRuleVersionRequest request, CancellationToken ct) { await ValidationRunner.ValidateAsync(rateValidator, request, ct); var saved=await repository.SaveRateVersionAsync(request,user.UserId,ct); await audit.AddAsync(new AuditEntryRequest("GstRateRuleVersions",saved.Id.ToString(),"Create",null,AuditSerializer.Serialize(saved),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse<GstRateRuleVersionDto>.Success(saved,"GST rate version created."); }
    public async Task<ApiResponse> SaveCategoryDefaultAsync(long categoryId, SaveCategoryHsnDefaultRequest request, CancellationToken ct) { await repository.SaveCategoryDefaultAsync(categoryId,request,user.UserId,ct); await audit.AddAsync(new AuditEntryRequest("CategoryHsnDefaults",categoryId.ToString(),"Update",null,AuditSerializer.Serialize(request),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse.Success("Category HSN default saved."); }
    public async Task<ApiResponse> SaveItemOverrideAsync(long itemId, SaveItemHsnOverrideRequest request, CancellationToken ct) { await repository.SaveItemOverrideAsync(itemId,request,user.UserId,ct); await audit.AddAsync(new AuditEntryRequest("ItemHsnOverrides",itemId.ToString(),"Update",null,AuditSerializer.Serialize(request),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse.Success("Product HSN override saved."); }
    public async Task<ApiResponse<EffectiveHsnMappingDto?>> GetEffectiveCategoryDefaultAsync(long categoryId, DateOnly onDate, CancellationToken ct) => ApiResponse<EffectiveHsnMappingDto?>.Success(await repository.GetEffectiveCategoryDefaultAsync(categoryId,onDate,ct));
    public async Task<ApiResponse<EffectiveHsnMappingDto>> RetireCategoryDefaultAsync(long categoryId,long mappingId,RetireHsnMappingRequest request,CancellationToken ct) { await ValidationRunner.ValidateAsync(retireValidator,request,ct); var retired=await repository.RetireCategoryDefaultAsync(categoryId,mappingId,request,user.UserId,ct); await audit.AddAsync(new AuditEntryRequest("CategoryHsnDefaults",mappingId.ToString(),"Retire",null,AuditSerializer.Serialize(retired),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse<EffectiveHsnMappingDto>.Success(retired,"Category HSN default retired."); }
    public async Task<ApiResponse<EffectiveHsnMappingDto>> RetireItemOverrideAsync(long itemId,long mappingId,RetireHsnMappingRequest request,CancellationToken ct) { await ValidationRunner.ValidateAsync(retireValidator,request,ct); var retired=await repository.RetireItemOverrideAsync(itemId,mappingId,request,user.UserId,ct); await audit.AddAsync(new AuditEntryRequest("ItemHsnOverrides",mappingId.ToString(),"Retire",null,AuditSerializer.Serialize(retired),user.UserId is null?null:checked((int)user.UserId.Value)),ct); return ApiResponse<EffectiveHsnMappingDto>.Success(retired,"Product HSN override retired."); }
    public async Task<ApiResponse<EffectiveProductClassificationDto>> GetEffectiveClassificationAsync(long itemId, DateOnly onDate, CancellationToken ct) => ApiResponse<EffectiveProductClassificationDto>.Success(await repository.GetEffectiveClassificationAsync(itemId,onDate,ct));
}
